fn bit_wise_xor(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Ensure both input arrays have the same length
    assert_eq!(arr1.len(), arr2.len(), "Input arrays must have the same length");

    // Perform element-wise XOR and collect the results
    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(a, b)| a ^ b)
        .collect()
}

